SELECT name, dish_id, setmeal_id, image, amount, SUM(number) AS number
FROM order_detail


        AND order_id IN

            #{id}



GROUP BY name, dish_id, setmeal_id, image, amount
ORDER BY number DESC;

SELECT s.*, SUM(od.number) AS salesCount FROM order_detail od JOIN setmeal s ON od.setmeal_id = s.id
AND od.order_id IN
#{id}
GROUP BY s.id ORDER BY salesCount DESC LIMIT 1;

